head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
scwin.vScrenID = "ULDBNS22400.xml";
scwin.vRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SearchList
 * 설명       : 목록을 조회한다.
 ***********************************************/
scwin.fn_SearchList = function() {
    // 버튼 중복 클릭을 방지
    scwin.fn_BtnDisable(bnt_Select, true);
    txb_TotalCnt.setValue("총 건");
    var param = '';
    param += "&{P}V_INST_CD=" + $c.stf.getObjectValue(txb_IsurCd); //발행기관코드
    param += "&{P}V_INST_NM=" + $c.stf.getObjectValue(txb_IsurNm); //발행기관명
    param += "&{P}V_CHRG_TP_CD=" + $c.stf.getObjectValue(cmb_ChrgTpCd); //담당자구분
    param += "&{P}V_BND_LIST_CORP_YN=" + $c.stf.getObjectValue(cmbBndListCorpYn); //채권상장법인여부

    var dsNm = 'BNS_BND_CHRG_LIST';
    var qryId = 'lds.stf.bnslistsrchl.select.bndChrgList';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List);
};


/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_NM: $c.stf.getObjectValue(txb_IsurNm)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    $c.stf.setObjectValue(txb_IsurNm, arrPar[0].ISUR_NM);
    $c.stf.setObjectValue(txb_IsurCd, arrPar[0].ISUR_CD);
};


/********************************************** 
 * 함수명   : fn_GetCommonKey
 * 설명       : 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetCommonKey = function(arrPar) {
    arrPar[0] = {
        STD_CD: dts_List.getCellData(dts_List.getRowPosition(), "STD_CD"),
        ISUR_CD: dts_List.getCellData(dts_List.getRowPosition(), "ISUR_CD"),
        APPL_ISU_SEQ: dts_List.getCellData(dts_List.getRowPosition(), "APPL_ISU_SEQ")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_SetHeader
 * 설명       : 데이터셋 헤더 세팅
 ***********************************************/
scwin.fn_SetHeader = function() {
    dts_Target.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=MAIL_RECEIPTPLACE_OUT";
    dts_Target.Reset();
};


/********************************************** 
 * 함수명   : fn_FindSmsTarget
 * 설명      : SMS전송버튼 클릭 시 전송대상을 dts_Target 에 세팅
 ***********************************************/
scwin.fn_FindSmsTarget = async function() {
    // 체크박스에 체크된것이 있는가?
    var idx = $c.cp.getValueRow(dts_List, 1, "T");
    if (idx == 0) {
        $c.win.alert("선택된 행이 존재하지 않습니다.");
        return;
    }
    dts_Target.removeAll();
    var cntTotal = 0; //전체 체크된 건수
    var cntSmsRcv_N = 0; //SMS수신여부가 N인 건수
    var cntEmptyCellPhoneNo = 0; //전화번호가 null인 건수
    var cntDupl = 0; //중복건수
    var chkDupl = 'N'; //중복여부

    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        // 체크박스 체크된것만..
        if (dts_List.getCellData(i, "CHK") != "T") {
            continue;
        }
        cntTotal++;

        // SMS수신여부가 N인것은 대상에서 제외
        if (dts_List.getCellData(i, "SMS_RCV_YN") != "Y") {
            //cntSmsRcv_N ++;

            //continue;

        }
        if (dts_List.getCellData(i, "CELLPHONE_NO") == "" || dts_List.getCellData(i, "CELLPHONE_NO") == "-") {
            cntEmptyCellPhoneNo++;
            continue;
        }
        chkDupl = 'N';
        for (var j = 1; j <= dts_Target.getTotalRow(); j++) {
            //alert(i+"::"+j+"::"+dts_List.NameString(i, "CHRG_NM")+"::"+dts_Target.NameString(j, "CHRG_NM")+"::"+dts_List.NameString(i, "CELLPHONE_NO")+"::"+dts_Target.NameString(j, "CELLPHONE_NO"));
            if (dts_List.getCellData(i, "CHRG_NM") == dts_Target.getCellData(j, "CHRG_NM") && dts_List.getCellData(i, "CELLPHONE_NO") == dts_Target.getCellData(j, "CELLPHONE_NO")) {
                cntDupl++;
                chkDupl = 'Y';
            }
        }
        //alert(cntDupl);

        if (chkDupl == 'N') {
            dts_Target.insertRow();
            var curRow = dts_Target.getRowPosition();
            dts_Target.setCellData(curRow, "CHECK", "T");
            dts_Target.setCellData(curRow, "ISUR_CD", dts_List.getCellData(i, "ISUR_CD"));
            dts_Target.setCellData(curRow, "COM_ABBRV", dts_List.getCellData(i, "ISUR_NM"));
            dts_Target.setCellData(curRow, "CHRG_NM", dts_List.getCellData(i, "CHRG_NM"));
            dts_Target.setCellData(curRow, "CELLPHONE_NO", dts_List.getCellData(i, "CELLPHONE_NO"));
            dts_Target.setCellData(curRow, "EMAIL", dts_List.getCellData(i, "EMAIL"));
        }
    }
    var strMsg = "";
    var strMsg1 = "";
    var strMsg2 = "";
    var strMsg3 = "";
    var strMsgT = "* 전체 선택 건수 : " + cntTotal;
    if (cntSmsRcv_N > 0) {
        //strMsg1 = "* SMS수신 미동의 건수 : " + cntSmsRcv_N;

    }
    if (cntEmptyCellPhoneNo > 0) {
        strMsg2 = "* 휴대전화번호 없는 건수 : " + cntEmptyCellPhoneNo;
    }
    if (cntDupl > 0) {
        strMsg3 = "* 중복된 휴대전화번호 건수 : " + cntDupl;
    }
    if (dts_Target.getTotalRow() == 0) {
        strMsg = "SMS 발신이 가능한 건이 존재하지 않습니다.\n";
        strMsg += "\n" + strMsgT;
        //strMsg += "\n" + strMsg1;
        strMsg += "\n" + strMsg2;
        strMsg += "\n" + strMsg3;
        $c.win.alert(strMsg);
        return;
    }
    if (cntDupl > 0 || cntEmptyCellPhoneNo > 0) {
        //strMsg = "[SMS수신 미동의]와 [휴대전화번호가 없는 것]을 제외하고 SMS가 발송됩니다.\n";
        strMsg = "[휴대전화번호가 없는 것]과 [중복된 휴대전화번호]를 제외하고\nSMS가 발송됩니다.\n";
        strMsg += "\n" + strMsgT;
        //strMsg += "\n" + strMsg1;
        strMsg += "\n" + strMsg2;
        strMsg += "\n" + strMsg3;
        $c.win.alert(strMsg);
    }
    await $c.frame.CreateDialogFrame("SENDSMS_NEW", "/bizspt/ULDSTF30308.gfm?MSG_GBN=", "문자보내기", 200, 50, 800, 665 + 30, "window");
};


/********************************************** 
 * 함수명   : fn_FindSmsTarget
 * 설명      : 메일발송버튼 클릭 시 발송대상을 dts_Target 에 세팅
 ***********************************************/
scwin.fn_FindMailTarget = async function() {
    // 체크박스에 체크된것이 있는가?
    var idx = $c.cp.getValueRow(dts_List, 1, "T");
    if (idx == 0) {
        $c.win.alert("선택된 행이 존재하지 않습니다.");
        return;
    }
    dts_Target.removeAll();
    var cntTotal = 0; //전체 체크된 건수
    var cntMailRcv_N = 0; //Mail수신여부가 N인 건수
    var cntEmptyMailAddr = 0; //전화번호가 null인 건수
    var cntDupl = 0; //중복건수
    var chkDupl = 'N'; //중복여부

    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        // 체크박스 체크된것만..
        if (dts_List.getCellData(i, "CHK") != "T") {
            continue;
        }
        cntTotal++;

        // Mail수신여부가 N인것은 대상에서 제외
        if (dts_List.getCellData(i, "EMAIL_RCV_YN") != "Y") {
            //cntMailRcv_N ++;

            //continue;

        }
        if (dts_List.getCellData(i, "EMAIL") == "" || dts_List.getCellData(i, "EMAIL") == "-") {
            cntEmptyMailAddr++;
            continue;
        }
        chkDupl = 'N';
        for (var j = 1; j <= dts_Target.getTotalRow(); j++) {
            //alert(i+"::"+j+"::"+dts_List.NameString(i, "CHRG_NM")+"::"+dts_Target.NameString(j, "CHRG_NM")+"::"+dts_List.NameString(i, "EMAIL")+"::"+dts_Target.NameString(j, "EMAIL"));
            if (dts_List.getCellData(i, "CHRG_NM") == dts_Target.getCellData(j, "CHRG_NM") && dts_List.getCellData(i, "EMAIL") == dts_Target.getCellData(j, "EMAIL")) {
                cntDupl++;
                chkDupl = 'Y';
            }
        }
        //alert(cntDupl);

        if (chkDupl == 'N') {
            dts_Target.insertRow();
            var curRow = dts_Target.getRowPosition();
            dts_Target.setCellData(curRow, "CHECK", "T");
            dts_Target.setCellData(curRow, "ISUR_CD", dts_List.getCellData(i, "ISUR_CD"));
            dts_Target.setCellData(curRow, "COM_ABBRV", dts_List.getCellData(i, "ISUR_NM"));
            dts_Target.setCellData(curRow, "CHRG_NM", dts_List.getCellData(i, "CHRG_NM"));
            dts_Target.setCellData(curRow, "EMAIL", dts_List.getCellData(i, "EMAIL"));
        }
    }
    var strMsg = "";
    var strMsg1 = "";
    var strMsg2 = "";
    var strMsg3 = "";
    var strMsgT = "* 전체 선택 건수 : " + cntTotal;
    if (cntMailRcv_N > 0) {
        //strMsg1 = "* 메일수신 미동의 건수 : " + cntMailRcv_N;

    }
    if (cntEmptyMailAddr > 0) {
        strMsg2 = "* 메일주소 없는 건수 : " + cntEmptyMailAddr;
    }
    if (cntDupl > 0) {
        strMsg3 = "* 중복된 메일주소 건수 : " + cntDupl;
    }
    if (dts_Target.getTotalRow() == 0) {
        strMsg = "메일발신이 가능한 건이 존재하지 않습니다.\n";
        strMsg += "\n" + strMsgT;
        //strMsg += "\n" + strMsg1;
        strMsg += "\n" + strMsg2;
        strMsg += "\n" + strMsg3;
        $c.win.alert(strMsg);
        return;
    }
    if (cntDupl > 0 || cntEmptyMailAddr > 0) {
        //strMsg = "[메일수신 미동의]와 [메일주소가 없는 것]을 제외하고 메일이 발송됩니다.\n";
        strMsg = "[메일주소가 없는 것]과 [중복된 메일주소]를 제외하고\n메일이 발송됩니다.\n";
        strMsg += "\n" + strMsgT;
        //strMsg += "\n" + strMsg1;
        strMsg += "\n" + strMsg2;
        strMsg += "\n" + strMsg3;
        $c.win.alert(strMsg);
    }
    await $c.frame.CreateDialogFrame("SENDMAIL_NEW", "/bizspt/ULDSTF30311.gfm?NOTI_SVC_ID=&ADD_INPUT=N&frameID=", "메일보내기", 200, 10, 790, 750 + 30, "window");
};


/******************************************************************* 
 * 함수명   : fn_CheckAll
 * 설명     : 전체 선택,취소를 설정한다.
 * argument : bCheck
 *******************************************************************/
scwin.fn_CheckAll = function(bCheck) {
    var isChecked = "";
    if (bCheck == '1') {
        isChecked = "T";
    } else {
        isChecked = "F";
    }
    grd_List.Redraw = false;
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        dts_List.setCellData(i, "CHK", isChecked);
    }
    grd_List.Redraw = true;
};


/******************************************************************* 
 * 함수명   : fn_CheckCheckbox
 * 설명     : 그리드의 체크박스를 체크/언체크한다.
 * argument : pCurrow
 *******************************************************************/
scwin.fn_CheckCheckbox = function(pCurrow) {
    if (dts_List.getCellData(pCurrow, "CHK") == "T") {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        dts_List.setCellData(pCurrow, "CHK", /*ORG SRC: dts_List.setNameString(pCurrow, "CHK", dts_List.NameString(pCurrow, "CHK") = );*/ X = X);
    } else {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        dts_List.setCellData(pCurrow, "CHK", /*ORG SRC: dts_List.setNameString(pCurrow, "CHK", dts_List.NameString(pCurrow, "CHK") = );*/ X = X);
    }
};
scwin.fn_DownloadExcel = function() {
    if (dts_List.getTotalRow() == 0) {
        return;
    }
    if (confirm("엑셀파일로 저장하시겠습니까?")) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewOffice(grd_List, "sheet1", "", 8, 0);
    }
};
scwin.fn_Search = function() {
    // 빈 함수.. 

    // SMS전송 팝업이 닫히면서 이 함수를 호출하게 되어있음.

    // 그러나 여기선 조회가 의미 없음.

};
scwin.fn_BtnDisable = function(pBtn, pDisable) {
    pBtn.setDisabled(pDisable);
    if (pDisable == true) {
        pBtn.src = "../img/bns/btn_select_nd.gif";
    } else {
        pBtn.src = "../img/bns/btn_select_n.gif";
    }
};
scwin.gform_onload = function() {
    $c.bns.BnsPanelToGroupBox(pnl_Search);
    scwin.fn_SetHeader();
};
scwin.bnt_Select_onclick = function() {
    scwin.fn_SearchList();
};
scwin.btn_Excel_onclick = function() {
    scwin.fn_DownloadExcel();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    txb_TotalCnt.setValue("총 " + rowcount + "건");
    $c.cm.CloseWin(rowcount, grd_List);

    // 버튼 중복 클릭을 방지
    scwin.fn_BtnDisable(bnt_Select, false);
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));

    // 버튼 중복 클릭을 방지
    scwin.fn_BtnDisable(bnt_Select, false);
};
scwin.btn_sendMail_onclick = function() {
    scwin.fn_FindMailTarget();
};
scwin.btn_sendSms_onclick = function() {
    scwin.fn_FindSmsTarget();
};
scwin.img_IsurNm_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsurCd;
    scwin.fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(img_IsurNm);
};
scwin.txb_IsurNm_onkeypress = function() {
    if (window.event.keyCode == 13) {
        scwin.fn_GetPar = fn_GetParIsurCd;
        scwin.fn_SetPar = fn_SetParIsurCd;
        $c.bns.fn_PopIsurSearch(img_IsurNm);
    }
};
scwin.grd_List_OnHeadCheckClick = function(col, colid, bCheck) {
    scwin.fn_CheckAll(bCheck);
};
scwin.grd_List_OnClick = function(row, colid) {
    if (colid == "CHK") {
        //fn_CheckCheckbox(row);

    }
};
scwin.txb_IsurNm_onchange = function() {
    $c.stf.setObjectValue(txb_IsurCd, "");
};
